import React from 'react';

const FilmCard = ({ film }) => {
    // Якщо ціни немає в базі, генеруємо її або ставимо заглушку
    const price = film.price || 150; 

    return (
        <article className="film-card">
            <div className="thumb">
                <img 
                    src={`/${film.image}`} 
                    alt={film.name} 
                    onError={(e) => (e.target.src = 'https://via.placeholder.com/300x450?text=No+Image')} 
                />
            </div>
            
            <div className="card-content">
                <h4>{film.name}</h4>
                
                <div className="film-details">
                    <div className="detail-row">
                        <span className="label">Rating:</span>
                        <span className="value rating">★ {film.IMDb_rating}</span>
                    </div>
                    <div className="detail-row">
                        <span className="label">Time:</span>
                        <span className="value">{film.time} min</span>
                    </div>
                    <div className="detail-row">
                        <span className="label">Price:</span>
                        <span className="value price">{price} UAH</span>
                    </div>
                </div>

                {/* Кнопка додавання в кошик (знадобиться для 10-ї лаби) */}
                <button className="add-cart-btn">Add to cart</button>
            </div>
        </article>
    );
};

export default FilmCard;
